   564  GF_Err gf_isom_write(GF_ISOFile *movie) {
   565          GF_Err e;
   566          if (movie == NULL) return GF_ISOM_INVALID_FILE;
   567          e = GF_OK;
   568
   569  #ifndef GPAC_DISABLE_ISOM_WRITE
   570          //write our movie to the file
   571          if ((movie->openMode != GF_ISOM_OPEN_READ) && (movie->openMode != GF_ISOM_OPEN_READ_EDIT)) {
   572                  gf_isom_get_duration(movie);
   573  #ifndef GPAC_DISABLE_ISOM_FRAGMENTS
   574                  //movie fragment mode, just store the fragment
   575                  if ( (movie->openMode == GF_ISOM_OPEN_WRITE) && (movie->FragmentsFlags & GF_ISOM_FRAG_WRITE_READY) ) {
   576                          e = gf_isom_close_fragments(movie);
   577                          if (e) return e;
   578                          //in case of mfra box usage -> create mfro, calculate box sizes and write it out
   579                          if (movie->mfra) {
   580                                  if (!movie->mfra->mfro) {
   581                                          movie->mfra->mfro = (GF_MovieFragmentRandomAccessOffsetBox *)gf_isom_box_new_parent(&movie->mfra->child_boxes, GF_ISOM_BOX_TYPE_MFRO);
   582                                          if (!movie->mfra->mfro) return GF_OUT_OF_MEM;
   583                                  }
   584                                  e = gf_isom_box_size((GF_Box *)movie->mfra);
   585                                  if (e) return e;
   586                                  movie->mfra->mfro->container_size = (u32) movie->mfra->size;
   587
   588                                  //write mfra
   589                                  if (!strcmp(movie->fileName, "_gpac_isobmff_redirect") && movie->on_block_out) {
   590                                          GF_BitStream *bs = gf_bs_new_cbk(movie->on_block_out, movie->on_block_out_usr_data, movie->on_block_out_block_size);
   591
   592                                          e = gf_isom_box_write((GF_Box *)movie->mfra, bs);
   593                                          gf_bs_del(bs);
   594                                  } else {
   595                                          e = gf_isom_box_write((GF_Box *)movie->mfra, movie->editFileMap->bs);
   596                                  }
   597                          }
   598                  } else
   599  #endif
   600                          e = WriteToFile(movie, GF_FALSE);
   601          }
   602  #endif /*GPAC_DISABLE_ISOM_WRITE*/
   603
   604  #ifndef GPAC_DISABLE_ISOM_FRAGMENTS
   605          if (movie->moov) {
   606                  u32 i;
   607                  for (i=0; i<gf_list_count(movie->moov->trackList); i++) {
   608                          GF_TrackBox *trak = (GF_TrackBox*)gf_list_get(movie->moov->trackList, i);
   609                          /*delete any pending dataHandler of scalable enhancements*/
   610                          if (trak->Media && trak->Media->information && trak->Media->information->scalableDataHandler && (trak->Media->information->scalableDataHandler != movie->movieFileMap))
   611                                  gf_isom_datamap_del(trak->Media->information->scalableDataHandler);
   612                  }
   613          }
   614  #endif
   615
   616          return e;
   617  }
